<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Creative Edge Parties - Mobile Catering</title>
    <style>
        :root {
            --primary-bg: #000000;
            --text-white: #ffffff;
            --accent-orange: #d35400;
            --font-main: 'Helvetica Neue', Helvetica, Arial, sans-serif;
            --spacing-unit: 16px;
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
            -webkit-tap-highlight-color: transparent;
        }

        body {
            font-family: var(--font-main);
            background-color: var(--primary-bg);
            color: var(--text-white);
            overflow-x: hidden;
            line-height: 1.4;
        }

        /* --- Header / Sticky Elements --- */
        .site-header {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 60px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 0 20px;
            z-index: 1000;
            background: linear-gradient(to bottom, rgba(0,0,0,0.6) 0%, rgba(0,0,0,0) 100%);
            transition: background 0.3s ease;
        }

        /* Scrolled state for header */
        .site-header.scrolled {
            background-color: rgba(0,0,0,0.95);
            backdrop-filter: blur(10px);
        }

        .logo-circle {
            width: 32px;
            height: 32px;
            background-color: white;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            color: black;
            font-weight: bold;
            font-size: 14px;
        }

        .menu-toggle {
            width: 30px;
            height: 20px;
            display: flex;
            flex-direction: column;
            justify-content: center;
            cursor: pointer;
        }

        .menu-toggle span {
            display: block;
            height: 2px;
            background-color: white;
            margin-bottom: 6px;
            transition: transform 0.3s;
        }

        .menu-toggle span:last-child {
            margin-bottom: 0;
            width: 70%;
            margin-left: auto; /* Align right like screenshot */
        }

        /* --- Hero Section --- */
        .hero {
            position: relative;
            height: 100vh;
            min-height: 700px;
            width: 100%;
            overflow: hidden;
            display: flex;
            flex-direction: column;
            justify-content: center;
            padding: 40px 24px;
        }

        .hero-bg {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            object-fit: cover;
            z-index: -1;
        }

        .hero-overlay {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: linear-gradient(to bottom, rgba(0,0,0,0.2) 0%, rgba(0,0,0,0.5) 100%);
            z-index: -1;
        }

        .hero-content {
            max-width: 600px;
            z-index: 2;
            animation: fadeInUp 1s ease-out forwards;
            opacity: 0;
            transform: translateY(20px);
        }

        @keyframes fadeInUp {
            to { opacity: 1; transform: translateY(0); }
        }

        .brand-label {
            font-size: 14px;
            letter-spacing: 2px;
            text-transform: uppercase;
            margin-bottom: 12px;
            color: #f0f0f0;
            font-weight: 300;
        }

        h1.hero-title {
            font-size: clamp(42px, 10vw, 72px); /* Fluid typography */
            font-weight: 300;
            letter-spacing: -1px;
            line-height: 1.05;
            margin-bottom: 20px;
            text-shadow: 0 2px 10px rgba(0,0,0,0.3);
        }

        .tagline {
            font-size: 14px;
            letter-spacing: 1.5px;
            text-transform: uppercase;
            margin-bottom: 80px; /* Space before locations */
            font-weight: 500;
            color: #fff;
        }

        .locations {
            font-size: 11px;
            letter-spacing: 2px;
            text-transform: uppercase;
            opacity: 0.9;
            font-weight: 400;
        }

        /* --- Clients Bar (Sticky Bottom of Hero) --- */
        .clients-bar {
            position: absolute;
            bottom: 0;
            left: 0;
            width: 100%;
            background-color: #000;
            padding: 18px 20px;
            text-align: center;
            font-size: 11px;
            letter-spacing: 2px;
            text-transform: uppercase;
            border-top: 1px solid #222;
            z-index: 10;
        }

        /* --- Menu Style (The "Drawer" or Overlay) --- */
        .mobile-menu {
            position: fixed;
            top: 0;
            right: -100%; /* Hidden off-screen */
            width: 85%;
            max-width: 320px;
            height: 100%;
            background-color: #111;
            padding: 80px 30px 40px;
            transition: right 0.4s cubic-bezier(0.25, 0.8, 0.25, 1);
            z-index: 2000;
            box-shadow: -5px 0 20px rgba(0,0,0,0.5);
            overflow-y: auto;
        }

        .mobile-menu.active {
            right: 0;
        }

        .menu-overlay {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(0,0,0,0.7);
            z-index: 1500;
            opacity: 0;
            visibility: hidden;
            transition: all 0.3s;
        }

        .menu-overlay.active {
            opacity: 1;
            visibility: visible;
        }

        .nav-link {
            display: block;
            color: #fff;
            text-decoration: none;
            font-size: 22px;
            font-weight: 300;
            padding: 15px 0;
            border-bottom: 1px solid #333;
            transition: padding-left 0.2s;
        }

        .nav-link:active {
            padding-left: 10px;
            color: var(--accent-orange);
        }

        /* --- CTA & Click-to-Call (Touch Design) --- */
        .cta-container {
            margin-top: 40px;
            display: flex;
            flex-direction: column;
            gap: 15px;
        }

        .btn-primary {
            display: block;
            width: 100%;
            padding: 18px;
            background-color: var(--accent-orange);
            color: white;
            text-align: center;
            text-decoration: none;
            font-size: 14px;
            font-weight: bold;
            letter-spacing: 1px;
            text-transform: uppercase;
            border-radius: 4px;
            box-shadow: 0 4px 15px rgba(211, 84, 0, 0.4);
            transition: transform 0.1s, background-color 0.2s;
            /* Touch target sizing */
            min-height: 48px; 
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .btn-primary:active {
            transform: scale(0.98);
            background-color: #b34200;
        }

        .click-to-call {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 10px;
            color: #ccc;
            text-decoration: none;
            font-size: 13px;
            padding: 15px;
            border: 1px solid #444;
            border-radius: 4px;
            transition: all 0.2s;
        }

        .click-to-call:active {
            background-color: #222;
            color: white;
        }

        .phone-icon {
            width: 18px;
            height: 18px;
            fill: currentColor;
        }

        /* --- Content Sections (Below Fold) --- */
        section {
            padding: 60px 20px;
            border-bottom: 1px solid #1a1a1a;
        }

        h2.section-title {
            font-size: 28px;
            font-weight: 300;
            margin-bottom: 30px;
            text-align: center;
        }

        .card-grid {
            display: grid;
            grid-template-columns: 1fr;
            gap: 20px;
        }

        .service-card {
            background: #151515;
            padding: 20px;
            border-radius: 8px;
            border: 1px solid #222;
        }

        .service-card h3 {
            font-size: 18px;
            margin-bottom: 10px;
            color: var(--accent-orange);
        }

        .service-card p {
            font-size: 14px;
            color: #aaa;
            line-height: 1.6;
        }

    </style>
</head>
<body>

    <!-- Sticky Header -->
    <header class="site-header" id="mainHeader">
        <div class="logo-circle">CEP</div>
        <div class="menu-toggle" id="menuToggle">
            <span></span>
            <span></span>
        </div>
    </header>

    <!-- Mobile Navigation Drawer -->
    <div class="menu-overlay" id="menuOverlay"></div>
    <nav class="mobile-menu" id="mobileMenu">
        <a href="#" class="nav-link">Services</a>
        <a href="#" class="nav-link">Menus</a>
        <a href="#" class="nav-link">Portfolio</a>
        <a href="#" class="nav-link">About Us</a>

        <!-- CTAs inside menu for easy access -->
        <div class="cta-container">
            <a href="tel:+15551234567" class="btn-primary">Book Now</a>
            <a href="tel:+15551234567" class="click-to-call">
                <svg class="phone-icon" viewBox="0 0 24 24">
                    <path d="M6.62 10.79c1.44 2.83 3.76 5.14 6.59 6.59l2.2-2.2c.27-.27.67-.36 1.02-.24 1.12.37 2.33.57 3.57.57.55 0 1 .45 1 1V20c0 .55-.45 1-1 1-9.39 0-17-7.61-17-17 0-.55.45-1 1-1h3.5c.55 0 1 .45 1 1 0 1.25.2 2.45.57 3.57.11.35.03.74-.25 1.02l-2.2 2.2z"/>
                </svg>
                Tap to Call
            </a>
        </div>
    </nav>

    <!-- Hero Section -->
    <main>
        <section class="hero">
            <!-- Using a high quality food texture image similar to the egg yolk/abstract food look -->
            <img src="https://images.unsplash.com/photo-1547592180-85f173990554?q=80&w=2070&auto=format&fit=crop" alt="Abstract Food Texture Background" class="hero-bg">
            <div class="hero-overlay"></div>

            <div class="hero-content">
                <p class="brand-label">Creative Edge Parties</p>
                <h1 class="hero-title">THE EGG<br>CAME FIRST.</h1>
                <p class="tagline">Reinventing Food as Design Since 1989.</p>
                <p class="locations">New York | Miami | Palm Beach | Worldwide</p>
            </div>

            <!-- Sticky Footer Element within Hero -->
            <div class="clients-bar">
                Select Clients
            </div>
        </section>

        <!-- Example Content to show scrolling behavior -->
        <section id="services">
            <h2 class="section-title">Our Services</h2>
            <div class="card-grid">
                <article class="service-card">
                    <h3>Corporate Events</h3>
                    <p>High-end catering solutions for product launches, galas, and executive retreats. We bring the design aesthetic to your table.</p>
                </article>
                <article class="service-card">
                    <h3>Private Parties</h3>
                    <p>Intimate dinners and large celebrations tailored to your personal taste. From cocktail hour to dessert.</p>
                </article>
                <article class="service-card">
                    <h3>Weddings</h3>
                    <p>A culinary experience that matches the grandeur of your special day. Custom menus designed around you.</p>
                </article>
            </div>

            <!-- Floating CTA for mobile context -->
            <div style="margin-top: 40px;">
                 <a href="#contact" class="btn-primary">Request a Proposal</a>
            </div>
        </section>
    </main>

    <script>
        // Interaction Logic for Mobile Touch Design

        const menuToggle = document.getElementById('menuToggle');
        const mobileMenu = document.getElementById('mobileMenu');
        const menuOverlay = document.getElementById('menuOverlay');
        const header = document.getElementById('mainHeader');

        // Toggle Menu
        function toggleMenu() {
            mobileMenu.classList.toggle('active');
            menuOverlay.classList.toggle('active');
            // Prevent body scroll when menu is open
            document.body.style.overflow = mobileMenu.classList.contains('active') ? 'hidden' : '';
        }

        menuToggle.addEventListener('click', toggleMenu);
        menuOverlay.addEventListener('click', toggleMenu);

        // Header Scroll Effect (Sticky behavior)
        window.addEventListener('scroll', () => {
            if (window.scrollY > 50) {
                header.classList.add('scrolled');
            } else {
                header.classList.remove('scrolled');
            }
        });

        // Simple active state feedback for links
        const navLinks = document.querySelectorAll('.nav-link');
        navLinks.forEach(link => {
            link.addEventListener('touchstart', () => {
                link.style.backgroundColor = '#222';
            }, {passive: true});
            link.addEventListener('touchend', () => {
                setTimeout(() => link.style.backgroundColor = 'transparent', 200);
            }, {passive: true});
        });
    </script>
</body>
</html>
